from __future__ import absolute_import

import logging

from taf.selenium.gnb.oam.coam.cu.pages import v22R1


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Configuration(v22R1.Configuration):
    """
    The class corresponding to Configuration page on selenium_coam web, all operations under Configuration
    page will be implemented or added in its corresponding classes.
    """

    _instance_dict = {}

    def __init__(self, driver, version):
        if not self._instance_dict:
            super(Configuration, self).__init__(driver, version)
            self._instance_dict.update({"Parameter Editor": ParameterEditorPageV22R2(driver, version)})


class ParameterEditorPageV22R2(v22R1.ParameterEditorPageV22R1):
    """
    As a class will be called by Configuration,
    all operations on Parameter Editor will be implemented under this class.
    """

    def __init__(self, driver, version):
        super(ParameterEditorPageV22R2, self).__init__(driver, version)
        self.MENU_ROUTE_LIST = ['settings', 'Configuration Management', 'Parameter Editor']
